-- blue-lantern (sha256 of the minified JSON: 881a06c5cce25422127251ee705654d235a5a01ca3032a867874ccc9fd1c905d)
insert into public.story_cases (id, case_text, updated_at) values ('blue-lantern', $case${
  "schema_version": 1,
  "id": "blue-lantern",
  "title": "The Blue Lantern",
